// AI: below section was generated by an AI
// Optional browser integration checks against isolated device API fixtures.
const {chromium}=require(process.env.PLAYWRIGHT_MODULE || 'playwright');
const fs=require('fs');
const path=require('path').join(__dirname,'../usermods/usermod_v2_icon256_wordclock/ui/');
const assert=require('node:assert/strict');
(async()=>{
const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH});
const page=await browser.newPage({viewport:{width:390,height:844}});
const errors=[],posts=[];
page.on('pageerror',e=>errors.push(e.message));
const a={look:0,color:16777215,gradient:0,direction:0};
const state={on:true,bri:128,mainseg:0,seg:[{id:0,fx:250,col:[[255,255,255]],sx:128}],Icon256:{active:true,clock:{...a},text:{...a},eq:{...a,look:1,gradient:4,direction:1},rain:{...a,look:2}}};
const info={name:'Test Icon256',ver:'test',icon256:{plate:2,modes:{clock:250,text:122,eq:139,rain:90}}};
const cfg={id:{name:info.name},if:{ntp:{tz:2}},nw:{ins:[{ssid:'Test WiFi'}]},um:{'Icon256 Word Clock':{Language:2,'Hide seconds':false,'German time of day':true},AudioReactive:{enabled:true}}};
await page.route('http://icon.test/**',async route=>{
const u=new URL(route.request().url());
let body,type='application/json';
if(route.request().method()==='POST'){
 const data=route.request().postDataJSON();posts.push({url:u.pathname,data});
 if(data.seg) Object.assign(state.seg[0],data.seg);
 if(data.Icon256) Object.assign(state.Icon256,data.Icon256);
 if(data.bri) state.bri=data.bri;
 body={success:true};
}else if(u.pathname==='/json')body={state,info};
else if(u.pathname==='/json/cfg')body=cfg;
else if(u.pathname==='/json/net')body={networks:[{ssid:'Music WiFi'}]};
else if(u.pathname==='/app.js'){body=fs.readFileSync(path+'app.js','utf8').replace('__GERMAN_TRANSLATIONS__',fs.readFileSync(path+'de.json','utf8'));type='application/javascript';}
else {body=fs.readFileSync(path+'index.html','utf8');type='text/html';}
await route.fulfill({status:200,contentType:type,body:typeof body==='string'?body:JSON.stringify(body)});
});
await page.routeWebSocket('ws://icon.test/ws',ws=>ws.onMessage(()=>{
const data=Buffer.alloc(772);data[0]=76;data[1]=2;data[2]=16;data[3]=16;data[4]=255;ws.send(data);
}));
await page.goto('http://icon.test/');
await page.waitForFunction(()=>document.getElementById('connection-status').textContent==='Connected');
await page.locator('[data-look="gradient"]').click();
await page.locator('[data-gradient="rainbow"]').click();
await page.locator('#direction').selectOption('diagonal');
await page.locator('[data-mode="eq"]').click();
await page.waitForTimeout(250);
await page.locator('[data-page="setup"]').click();
await page.locator('#device-name').waitFor();
await page.waitForFunction(()=>document.getElementById('device-name').value==='Test Icon256');
await page.locator('#ui-language').selectOption('de');
await page.locator('#hide-seconds').check();
await page.locator('#setup-form button[type="submit"]').click();
await page.waitForFunction(()=>document.getElementById('save-status').textContent==='Einstellungen gespeichert.');
if (process.env.SCREENSHOT_DIR) await page.screenshot({path:process.env.SCREENSHOT_DIR+'/icon256-setup.png',fullPage:true});
await page.locator('[data-page="control"]').click();
if (process.env.SCREENSHOT_DIR) await page.screenshot({path:process.env.SCREENSHOT_DIR+'/icon256-control.png',fullPage:true});
const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);
assert.deepEqual(errors,[]);
assert.equal(overflow,false);
assert(posts.some(p=>p.data.um?.['Icon256 Word Clock']?.['Hide seconds']));
assert(posts.some(p=>p.data.Icon256?.clock?.direction===2));
assert(posts.some(p=>p.data.AudioReactive?.enabled));
assert.equal(await page.locator('[data-plate=de] [data-cell="0"]').evaluate(el=>el.style.color),'rgb(255, 0, 0)');
await page.locator('[data-mode="rain"]').click();
await page.waitForTimeout(200);
assert(posts.some(p=>p.data.seg?.fx===90 && p.data.seg?.o1===true));
await page.locator('[data-mode="text"]').click();
await page.waitForTimeout(200);
await page.locator('#message').fill('<b>Hello</b>');
await page.waitForTimeout(300);
assert(posts.some(p=>p.data.seg?.n==='<b>Hello</b>'));
assert.equal(await page.locator('#message b').count(),0);
await page.setViewportSize({width:1280,height:900});
assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
console.log('Icon256 UI: mobile/desktop, translations, live SVG, mode defaults, gradient payloads, text and setup passed.');
await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

// AI: end
